items.solution:
function mixHash(salt, password) {
  const combined = salt + password;
  let hash = 0;
  for (let i = 0; i < combined.length; i++) {
    hash = ((hash * 33) ^ combined.charCodeAt(i)) | 0;
  }
  return hash;
}
